#include "visualizer_library.h"
int main(){MilkdropBrowser milk;const char *names[]={"WAVEFORM"};VisualizerLibrary a(milk,names,1),b(milk,names,1);assert(a.appearance.theme==0&&a.appearance.font==0);a.appearance.theme=4;a.appearance.font=2;a.appearance.hudSeconds=15;a.appearance.sensitivity=6;a.appearance.stats=true;a.toggleFavorite(1);assert(b.decode(a.encode()));assert(b.appearance.theme==4&&b.appearance.font==2&&b.appearance.hudSeconds==15&&b.appearance.sensitivity==6&&b.appearance.stats&&b.favorite(-1));assert(b.decode("HYPNOTIC_UI_1\nV\t1\nF\tbuiltin:0\n"));assert(b.appearance.theme==0&&b.appearance.hudSeconds==5&&b.favorite(-1));for(const char *bad:{"9,0,5,2,0","0,5,5,2,0","0,0,0,2,0","0,0,5,9,0","0,0,5,2,5","0,0,5,2,0oops"}){assert(b.decode(std::string("HYPNOTIC_UI_1\nU\t")+bad+"\n"));assert(b.appearance.theme==0&&b.appearance.font==0&&b.appearance.hudSeconds==5&&!b.appearance.stats);}puts("PASS all UI settings save/reload, existing favorites, old preference migration and invalid values");}
